:root{color-scheme:dark;--bg:#111113;--panel:#19191d;--line:#303036;--muted:#929098;--pink:#ff5c9c;--mint:#a7f3db}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 54% -15%,#392039 0,transparent 45%),var(--bg);color:#f8f4f2;font:14px/1.4 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;min-height:100vh}.shell{max-width:1380px;margin:auto;padding:24px 34px 32px}.top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:17px}.brand{display:flex;align-items:center;gap:12px}.mark{width:34px;height:34px;border:1px solid #ff76a8;border-radius:10px;display:grid;place-items:center;color:#ff76a8;font-weight:900;font-size:20px;box-shadow:0 0 22px #ff4d8725}.brand strong{font-size:15px;letter-spacing:.16em}.brand small{display:block;color:#8f8992;font-size:10px;letter-spacing:.18em;margin-top:1px}.topright{color:#aaa5aa;font-size:12px;letter-spacing:.06em}.topright span{color:var(--mint)}.intro{padding:27px 0 22px;display:flex;justify-content:space-between;align-items:end}.eyebrow{font-size:10px;letter-spacing:.2em;color:#ff77a7;text-transform:uppercase;font-weight:700}.intro h1{font-size:clamp(24px,3vw,36px);margin:6px 0 0;letter-spacing:-.045em}.intro p{margin:5px 0 0;color:#a6a0a6}.layout{display:grid;grid-template-columns:304px minmax(0,1fr);gap:22px;align-items:start}.controls{background:linear-gradient(155deg,#1d1b20,#17171a 62%);border:1px solid var(--line);border-radius:14px;padding:18px;box-shadow:0 18px 50px #0003}.group{margin-bottom:17px}.labelrow{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.labelrow label,.fieldlabel{font-size:11px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;color:#d4cfd3}.hint{font-size:10px;color:#77737a}.samples{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.sample{padding:0;border-radius:8px;border:1px solid #35333a;background:#222;overflow:hidden;cursor:pointer;color:#bcb6bc;text-align:left}.sample:hover,.sample.active{border-color:#ff679e;box-shadow:0 0 0 1px #ff679e44}.sample canvas{display:block;width:100%;height:56px;object-fit:cover}.sample span{display:block;font-size:10px;padding:5px 7px}.upload{height:39px;border:1px dashed #514b55;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#c4bdc3;cursor:pointer;font-size:12px}.upload:hover{border-color:#ff679e;color:#fff}.upload input{display:none}input[type=text],select{width:100%;height:39px;background:#111114;border:1px solid #36343a;border-radius:8px;color:#f6f0f3;padding:0 11px;font:inherit;font-size:13px;outline:none}input[type=text]:focus,select:focus{border-color:#ff679e}.palette{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}.swatch{border:1px solid #39363d;border-radius:8px;background:#151518;padding:8px 6px;color:#bdb7be;font-size:10px;cursor:pointer;text-align:center}.swatch i{display:block;height:17px;border-radius:4px;margin-bottom:6px}.swatch.selected{border-color:#ff679e;color:white}.toggles{display:flex;gap:8px}.toggle{flex:1;display:flex;align-items:center;gap:7px;padding:9px;border:1px solid #35333a;background:#111114;border-radius:8px;color:#c7c0c7;font-size:11px}.toggle input{accent-color:#ff5c9c}.export{width:100%;height:45px;border:0;border-radius:9px;background:linear-gradient(105deg,#ff5590,#ff8a65);color:#231018;font-size:12px;font-weight:900;letter-spacing:.12em;cursor:pointer;box-shadow:0 8px 24px #ff558a26}.export:hover{filter:brightness(1.08);transform:translateY(-1px)}.status{height:15px;color:var(--mint);font-size:10px;text-align:center;margin-top:8px}.stage{min-width:0}.stagehead{display:flex;justify-content:space-between;align-items:center;color:#9f99a0;font-size:10px;text-transform:uppercase;letter-spacing:.13em;margin:2px 0 10px}.live{color:#9eebcd}.preview{padding:12px;background:linear-gradient(140deg,#201d22,#161619);border:1px solid var(--line);border-radius:14px;box-shadow:0 22px 65px #0005}.canvaswrap{width:100