<script>
(()=>{'use strict';const $=s=>document.querySelector(s),canvas=$('#cover'),ctx=canvas.getContext('2d'),palettes={vice:{sky:'#ffad72',mid:'#ed5c89',deep:'#392b70',glow:'#ffe092',ink:'#271630'},midnight:{sky:'#56d9df',mid:'#4c78c9',deep:'#292568',glow:'#a9fbff',ink:'#111b3b'},tropical:{sky:'#f2d36c',mid:'#52caa1',deep:'#167b9e',glow:'#edffb0',ink:'#12394a'}};let state={scene:'coast',palette:'vice',photo:null,halftone:true,grain:true,title:'NEON TIDES',subtitle:'EVERY PARADISE HAS A PRICE',size:[1080,1080]};
function rr(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r)}function line(c,x1,y1,x2,y2,color,width=2){c.strokeStyle=color;c.lineWidth=width;c.beginPath();c.moveTo(x1,y1);c.lineTo(x2,y2);c.stroke()}
function skyline(c,x,y,w,h,color,seed=2){let v=seed;const rand=()=>{v=(v*16807)%2147483647;return v/2147483647};c.fillStyle=color;let xx=x;while(xx<x+w){let bw=18+rand()*38,bh=h*(.17+rand()*.55);c.fillRect(xx,y+h-bh,bw,bh);if(bw>25){c.fillStyle='#ffe9b080';for(let wy=y+h-bh+8;wy<y+h-8;wy+=11)for(let wx=xx+6;wx<xx+bw-3;wx+=9)if(rand()>.48)c.fillRect(wx,wy,3,4);c.fillStyle=color}xx+=bw+3}}
function scene(c,x,y,w,h,type,p){const g=c.createLinearGradient(x,y,x+w*.18,y+h);g.addColorStop(0,p.sky);g.addColorStop(.45,p.mid);g.addColorStop(1,p.deep);c.fillStyle=g;c.fillRect(x,y,w,h);let sunx=x+w*.73,suny=y+h*.36,r=h*.2;let sg=c.createRadialGradient(sunx,suny,1,sunx,suny,r*1.7);sg.addColorStop(0,p.glow+'ee');sg.addColorStop(1,p.glow+'00');c.fillStyle=sg;c.fillRect(x,y,w,h);c.fillStyle=p.glow;c.beginPath();c.arc(sunx,suny,r,0,Math.PI*2);c.fill();c.save();c.beginPath();c.arc(sunx,suny,r,0,Math.PI*2);c.clip();c.fillStyle=p.mid;for(let k=0;k<8;k++)c.fillRect(sunx-r,suny-r+k*r*.3,r*2,k%2?2:3);c.restore();
if(type==='coast'){let sea=c.createLinearGradient(x,y+h*.58,x,y+h);sea.addColorStop(0,'#fa986c');sea.addColorStop(.4,p.deep);sea.addColorStop(1,'#10192e');c.fillStyle=sea;c.fillRect(x,y+h*.57,w,h*.43);for(let i=0;i<15;i++){let yy=y+h*(.63+i*.025),ww=w*(.12+(i%4)*.09);line(c,sunx-ww/2,yy,sunx+ww/2,yy,'#ffeaa688',Math.max(1,h*.003))}skyline(c,x,y+h*.4,w,h*.28,'#30243d',9);c.fillStyle='#142032';c.beginPath();c.moveTo(x,y+h*.73);c.lineTo(x+w*.13,y+h*.58);c.lineTo(x+w*.23,y+h*.74);c.lineTo(x+w*.31,y+h*.61);c.lineTo(x+w*.43,y+h*.78);c.lineTo(x+w*.55,y+h*.7);c.lineTo(x+w*.68,y+h*.81);c.lineTo(x+w*.8,y+h*.69);c.lineTo(x+w,y+h*.79);c.lineTo(x+w,y+h);c.lineTo(x,y+h);c.fill();}else if(type==='tower'){c.fillStyle='#211f3d';c.beginPath();c.moveTo(x+w*.08,y+h);c.lineTo(x+w*.27,y+h*.35);c.lineTo(x+w*.4,y+h*.35);c.lineTo(x+w*.49,y+h);c.fill();c.fillStyle='#322549';c.beginPath();c.moveTo(x+w*.52,y+h);c.lineTo(x+w*.63,y+h*.2);c.lineTo(x+w*.78,y+h*.2);c.lineTo(x+w*.95,y+h);c.fill();skyline(c,x,y+h*.52,w,h*.4,'#332241',27);for(let j=0;j<7;j++){line(c,x+w*(.3+j*.023),y+h*.47,x+w*(.37+j*.018),y+h*.96,'#ffda8760',1)}}else{let sea=c.createLinearGradient(x,y+h*.5,x,y+h);sea.addColorStop(0,'#ffc071');sea.addColorStop(1,'#146e87');c.fillStyle=sea;c.fillRect(x,y+h*.52,w,h*.48);for(let j=0;j<3;j++){let px=x+w*(.2+j*.27);c.fillStyle='#152f39';c.fillRect(px,y+h*.46,w*.012,h*.32);c.fillStyle='#163e45';c.beginPath();c.ellipse(px,y+h*.44,w*.1,h*.045,-.25,Math.PI,Math.PI*2);c.fill();for(let a=-1;a<=1;a++){c.beginPath();c.ellipse(px+a*w*.06,y+h*.38,w*.07,h*.028,a*.3,Math.PI,Math.PI*2);c.fill()}}}c.fillStyle='#15152b';c.fillRect(x,y+h*.94,w,h*.06);for(let i=0;i<20;i++){let xx=x+i*w/20;line(c,xx,y+h*.94,xx+w*.12,y+h,'#ffad7588',1)}}
function fillCoverPhoto(c,x,y,w,h,p){if(state.photo){let im=state.photo,s=Math.max(w/im.width,h/im.height),iw=im.width*s,ih=im.height*s;c.drawImage(im,x+(w-iw)/2,y+(h-ih)/2,iw,ih);c.fillStyle=p.mid+'55';c.fillRect(x,y,w,h)}else scene(c,x,y,w,h,state.scene,p)}
function panel(c,x,y,w,h,tag,p,type){c.save();rr(c,x,y,w,h,8);c.clip();scene(c,x,y,w,h,type,p);c.fillStyle='#100e1c99';c.fillRect(x,y+h*.72,w,h*.28);c.fillStyle='#fff';c.font='800 '+Math.max(10,h*.09)+'px Arial';c.letterSpacing='2px';c.fillText(tag.toUpperCase(),x+w*.08,y+h*.9);c.restore();c.strokeStyle='#fff9';c.lineWidth=2;c.strokeRect(x+1,y+1,w-2,h-2)}
function halftone(c,w,h){c.save();c.fillStyle='#130d1d';for(let y=0;y<h;y+=9)for(let x=0;x<w;x+=9){if(((x+y)%27)<14)c.globalAlpha=.14,c.beginPath(),c.arc(x,y,1.25,0,6.29),c.fill()}c.globalAlpha=1;c.restore()}
function draw(){let [w,h]=state.size;canvas.width=w;canvas.height=h;let c=ctx,p=palettes[state.palette];c.fillStyle='#17101c';c.fillRect(0,0,w,h);let m=w*.045,top=h*.045,header=h*.072,footer=h*.035,gap=w*.018,contentY=top+header+gap,contentH=h-footer-contentY-gap; // framed magazine grid
c.fillStyle='#fff';c.fillRect(m,top,w-m*2,header);c.fillStyle=p.ink;c.font='900 '+Math.round(header*.33)+'px Arial';c.letterSpacing='3px';c.fillText('VICE FRAME',m+header*.22,top+header*.44);c.font='700 '+Math.round(header*.12)+'px Arial';c.letterSpacing='2px';c.fillText('MIAMI  /  AFTER DARK',m+header*.22,top+header*.78);c.textAlign='right';c.font='900 '+Math.round(header*.2)+'px Arial';c.fillText('VOL. 06  •  SUMMER EDITION',w-m-header*.2,top+header*.57);c.textAlign='left';
let heroW=w*.63,panX=m+heroW+gap,panW=w-m-panX,panH=(contentH-gap*2)/3;let hx=m,hy=contentY,heroH=contentH; c.save();rr(c,hx,hy,heroW,heroH,8);c.clip();fillCoverPhoto(c,hx,hy,heroW,heroH,p);let shade=c.createLinearGradient(0,hy+heroH*.35,0,hy+heroH);shade.addColorStop(0,'#130f1c00');shade.addColorStop(.7,'#160c28b0');shade.addColorStop(1,'#110c20ee');c.fillStyle=shade;c.fillRect(hx,hy,heroW,heroH);c.restore();c.strokeStyle='#fff9';c.lineWidth=2;c.strokeRect(hx+1,hy+1,heroW-2,heroH-2);
panel(c,panX,contentY,panW,panH,'01 / The coast',p,'coast');panel(c,panX,contentY+panH+gap,panW,panH,'02 / The city',p,'tower');panel(c,panX,contentY+(panH+gap)*2,panW,panH,'03 / No sleep',p,'palm');
// masthead typography, original condensed system type
let title=(state.title||'YOUR STORY').toUpperCase(),subtitle=(state.subtitle||'').toUpperCase();c.save();c.shadowColor='#201021';c.shadowBlur=w*.012;c.fillStyle='#fff';c.textAlign='left';let tx=hx+heroW*.065,base=hy+heroH*.76,fs=Math.min(heroW*.15,heroH*.115);c.font='1000 '+fs+'px Impact,"Arial Narrow",sans-serif';while(c.measureText(title).width>heroW*.87&&fs>14){fs-=2;c.font='1000 '+fs+'px Impact,"Arial Narrow",sans-serif'}c.lineWidth=Math.max(2,fs*.018);c.strokeStyle='#27172c';c.strokeText(title,tx,base);c.fillText(title,tx,base);c.shadowBlur=0;c.fillStyle=p.glow;c.font='800 '+Math.max(12,fs*.16)+'px Arial';c.letterSpacing='3px';c.fillText(subtitle,tx,base+fs*.28);c.restore();
// original age-style mark, edition ribbon, price and barcode
let bx=hx+heroW*.78,by=hy+heroH*.055,bs=heroW*.14;c.fillStyle='#f7efe6';c.fillRect(bx,by,bs,bs*1.12);c.fillStyle='#161020';c.textAlign='center';c.font='900 '+bs*.52+'px Arial';c.fillText('16',bx+bs/2,by+bs*.62);c.font='800 '+bs*.11+'px Arial';c.fillText('NIGHT',bx+bs/2,by+bs*.8);c.fillText('SHIFT',bx+bs/2,by+bs*.94);c.textAlign='left';let stripY=hy+heroH*.91;c.fillStyle=p.glow;c.fillRect(hx,stripY,heroW,heroH*.045);c.fillStyle=p.ink;c.font='900 '+Math.max(9,heroH*.023)+'px Arial';c.letterSpacing='2px';c.fillText('NEON NEVER SLEEPS  •  ORIGINAL CITY STORIES',hx+heroW*.04,stripY+heroH*.031);
// barcode tucked into bottom edge
let barY=hy+heroH*.965,barX=hx+heroW*.78;c.fillStyle='#fff';c.fillRect(barX,barY,heroW*.2,heroH*.025);for(let i=0;i<37;i++){let xx=barX+heroW*.008+i*heroW*.0048;if((i*7)%5!==0){c.fillStyle='#17101c';c.fillRect(xx,barY+heroH*.002,((i*3)%3+1)*heroW*.0012,heroH*.016)}}
// bottom folio and print registration details
c.fillStyle='#160f20';c.fillRect(m,h-footer,w-m*2,footer);c.fillStyle='#f8eadd';c.font='700 '+Math.max(9,footer*.37)+'px Arial';c.letterSpacing='2px';c.fillText('VICE CITY • THE GOOD LIFE, COMPLICATED',m+footer*.25,h-footer*.38);c.textAlign='right';c.fillText('COLLECTOR SERIES      01 / 06',w-m-footer*.25,h-footer*.38);c.textAlign='left';if(state.halftone)halftone(c,w,h);if(state.grain){let seed=411;for(let i=0;i<Math.floor(w*h/550);i++){seed=(seed*16807)%2147483647;let xx=seed%w;seed=(seed*16807)%2147483647;let yy=seed%h;c.fillStyle=seed%2?'#fff':'#000';c.globalAlpha=.12;c.fillRect(xx,yy,1.3,1.3)}c.globalAlpha=1}$('#resolution').textContent=w+' × '+h}
function renderThumbs(){document.querySelectorAll('.sample').forEach(b=>{let c=b.querySelector('canvas').getContext('2d');scene(c,0,0,120,64,b.dataset.scene,palettes.vice)})}function redraw(){draw()}
document.querySelectorAll('.sample').forEach(b=>b.onclick=()=>{state.scene=b.dataset.scene;state.photo=null;document.querySelectorAll('.sample').forEach(x=>x.classList.toggle('active',x===b));draw()});document.querySelectorAll('.swatch').forEach(b=>b.onclick=()=>{state.palette=b.dataset.palette;document.querySelectorAll('.swatch').forEach(x=>x.classList.toggle('selected',x===b));draw()});$('#title').oninput=e=>{state.title=e.target.value;draw()};$('#subtitle').oninput=e=>{state.subtitle=e.target.value;draw()};$('#halftone').onchange=e=>{state.halftone=e.target.checked;draw()};$('#grain').onchange=e=>{state.grain=e.target.checked;draw()};$('#size').onchange=e=>{state.size=e.target.value.split(',').map(Number);draw()};$('#photo').onchange=e=>{let f=e.target.files&&e.target.files[0];if(!f)return;let reader=new FileReader();reader.onload=()=>{let im=new Image();im.onload=()=>{state.photo=im;document.querySelectorAll('.sample').forEach(x=>x.classList.remove('active'));draw()};im.src=reader.result};reader.readAsDataURL(f)};$('#export').onclick=()=>{canvas.toBlob(b=>{if(!b)return;let a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='vice-frame-'+state.size.join('x')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500);$('#status').textContent='Cover exported · '+state.size.join(' × ')+' PNG'},'image/png')};
renderThumbs();let q=new URLSearchParams(location.search),shot=q.get('shot');if(shot==='cover'){document.body.classList.add('shot-cover');state.scene=q.get('scene')||'coast';state.palette=q.get('palette')||state.palette;state.title=q.get('title')||'NEON TIDES';state.subtitle=q.get('subtitle')||'EVERY PARADISE HAS A PRICE';$('#title').value=state.title;$('#subtitle').value=state.subtitle}if(shot==='editor'){state.palette='midnight';state.scene='tower';state.title='BOULEVARD QUEEN';state.subtitle='SHE OWNS THE NIGHT';state.size=[1080,1350];$('#title').value=state.title;$('#subtitle').value=state.subtitle;$('.swatch[data-palette="midnight"]').click();$('#size').value='1080,1350'}if(shot==='variant'){state.palette='tropical';state.scene='palm';state.title='AFTERGLOW';state.subtitle='THE CITY IS YOURS';state.size=[1920,1080];$('#title').value=state.title;$('#subtitle').value=state.subtitle;$('.swatch[data-palette="tropical"]').click();$('#size').value='1920,1080'}draw();requestAnimationFrame(()=>requestAnimationFrame(()=>window.__shotReady=true));})();
</script></body></html>
